body.script:
// === 实时追踪页滚动变形脚本 ===
// 对应规范：小程序动画与布局实现规范.md 第 2.2 节
// 在微信小程序中：把 .phone 的 scroll 事件替换为 scroll-view 的 bindscroll，
// 把 setProperty 更新 CSS 变量替换为 setData 动态绑定 style。
(function () {
  const phone = document.querySelector('.phone[data-dom-id="page-client-order-tracking"]');
  if (!phone) return;

  const navBar = phone.querySelector('.nav-bar');
  const buttons = phone.querySelectorAll('.nav-bar .nav-icon-btn');
  const revealEls = phone.querySelectorAll('.tracking-worker-card, .tracking-timeline-card, .order-detail-link');
  const staggerItems = phone.querySelectorAll('.tt-item');

  if (navBar) {
    navBar.classList.add('morphing');
    // 移除 HTML 内联的 2px 圆角，让 CSS 变量接管
    navBar.style.borderBottomLeftRadius = '';
    navBar.style.borderBottomRightRadius = '';
  }

  revealEls.forEach(el => el.classList.add('morph-reveal'));
  staggerItems.forEach((el, i) => {
    el.classList.add('morph-reveal-item');
    el.style.setProperty('--item-index', String(i));
  });

  function syncMorph() {
    const y = phone.scrollTop || 0;
    const morphP = Math.min(Math.max(y / 120, 0), 1);
    const revealStart = 120;
    const revealRange = 80;
    const revealP = Math.min(Math.max((y - revealStart) / revealRange, 0), 1);

    // 1) 导航栏 → Hero 形态
    phone.style.setProperty('--morph-p', morphP.toFixed(4));
    phone.style.setProperty('--reveal-p', revealP.toFixed(4));
    phone.style.setProperty('--nav-pt', (18 + 20 * morphP) + 'px');
    phone.style.setProperty('--nav-pb', (18 + 6 * morphP) + 'px');
    phone.style.setProperty('--nav-ph', (20 + 4 * morphP) + 'px');
    phone.style.setProperty('--nav-radius', (28 + 4 * morphP) + 'px');
    phone.style.setProperty('--btn-size', (44 - 4 * morphP) + 'px');

    // 2) 地图区域高度 420px → 120px，同时轻微缩小并淡出
    phone.style.setProperty('--map-h', Math.max(120, 420 - 300 * morphP) + 'px');

    // 3) 状态横幅从地图底部漂浮到 Hero 下方（filter-tabs 位置）
    // 初始位置约 phone 顶部下 468px；目标位置约 84px；差值约 106px 由 transform 补足
    phone.style.setProperty('--status-translate', (-106 * morphP) + 'px');
    phone.style.setProperty('--status-mt', (-32 + 14 * morphP) + 'px');

    // 4) 两侧按钮由新拟态圆钮渐变为玻璃圆钮
    const p = morphP;
    const bgMix = `color-mix(in srgb, var(--bg-elevated) ${(1 - p) * 100}%, rgba(255,255,255,0.18) ${p * 100}%)`;
    const border = p < 0.02 ? 'none' : `0.5px solid rgba(255,255,255,${(0.30 * p).toFixed(2)})`;
    const shadows = [];
    if (p < 0.98) {
      const q = 1 - p;
      shadows.push(`${6 * q}px ${6 * q}px 14px rgba(221,214,206,${(0.76 * q).toFixed(2)})`);
      shadows.push(`${-6 * q}px ${-6 * q}px 14px rgba(255,248,242,${(0.55 * q).toFixed(2)})`);
      shadows.push(`0 ${4 * q}px ${16}px rgba(0,0,0,${(0.04 * q).toFixed(2)})`);
      shadows.push(`inset 0 1px 1px rgba(255,255,255,${(0.45 * q).toFixed(2)})`);
    }
    if (p > 0.02) {
      shadows.push(`inset 0 1px 2px rgba(255,255,255,${(0.30 * p).toFixed(2)})`);
    }
    const boxShadow = shadows.join(', ');
    const backdrop = `blur(${16 * p}px)`;
    buttons.forEach(btn => {
      btn.style.background = bgMix;
      btn.style.border = border;
      btn.style.boxShadow = boxShadow;
      btn.style.backdropFilter = backdrop;
      btn.style.webkitBackdropFilter = backdrop;
    });

    // 5) 下方内容依次揭示（stagger 约 24px/项）
    staggerItems.forEach((item, i) => {
      const offset = 24 * i;
      const itemP = Math.min(Math.max((y - revealStart - offset) / revealRange, 0), 1);
      item.style.setProperty('--item-reveal-p', itemP.toFixed(4));
    });
  }

  syncMorph();
  phone.addEventListener('scroll', syncMorph, { passive: true });
  window.addEventListener('resize', syncMorph, { passive: true });
})();
